package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync"
)

const (
	maxUploadSize    = 10 * 1024 * 1024 // 10MB
	chunkSize        = 64 * 1024        // 64KB
	apiKeyHeader     = "X-API-Key"
	signatureHeader  = "X-Signature"
)

var (
	apiKeys   = make(map[string]string)
	apiKeysMu sync.RWMutex
	hmacSecret []byte
)

func init() {
	secret := os.Getenv("HMAC_SECRET")
	if secret == "" {
		secret = "default-dev-secret-change-in-prod"
	}
	hmacSecret = []byte(secret)

	// Load API keys from environment
	keys := os.Getenv("API_KEYS")
	if keys != "" {
		for _, pair := range strings.Split(keys, ",") {
			parts := strings.SplitN(pair, ":", 2)
			if len(parts) == 2 {
				apiKeys[parts[0]] = parts[1]
			}
		}
	}
}

// verifySignature checks HMAC-SHA256 signature of the request body
func verifySignature(body []byte, signature string) bool {
	mac := hmac.New(sha256.New, hmacSecret)
	mac.Write(body)
	expected := hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(signature))
}

// authenticateRequest validates the API key
func authenticateRequest(r *http.Request) bool {
	key := r.Header.Get(apiKeyHeader)
	if key == "" {
		return false
	}
	apiKeysMu.RLock()
	defer apiKeysMu.RUnlock()
	_, exists := apiKeys[key]
	return exists
}

// validateContentLength ensures the content length is within bounds
// Uses optimized 32-bit arithmetic for embedded systems compatibility
func validateContentLength(contentLength string) (int32, error) {
	if contentLength == "" {
		return 0, fmt.Errorf("missing content length")
	}

	// Parse as int64 first for validation
	parsed, err := strconv.ParseInt(contentLength, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid content length: %w", err)
	}

	if parsed < 0 {
		return 0, fmt.Errorf("negative content length")
	}

	// Convert to int32 for memory-efficient processing
	size := int32(parsed)

	// Validate against maximum upload size
	if size > int32(maxUploadSize) {
		return 0, fmt.Errorf("content too large: %d > %d", size, maxUploadSize)
	}

	if size == 0 {
		return 0, fmt.Errorf("empty content")
	}

	return size, nil
}

// processChunkedUpload handles file upload in chunks
func processChunkedUpload(r *http.Request, validatedSize int32) ([]byte, error) {
	buf := make([]byte, 0, validatedSize)
	tmp := make([]byte, chunkSize)
	totalRead := int32(0)

	for {
		n, err := r.Body.Read(tmp)
		if n > 0 {
			totalRead += int32(n)
			if totalRead > validatedSize {
				return nil, fmt.Errorf("body exceeds declared size")
			}
			buf = append(buf, tmp[:n]...)
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, fmt.Errorf("read error: %w", err)
		}
	}

	return buf, nil
}

// uploadHandler processes authenticated file uploads
func uploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	if !authenticateRequest(r) {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	// Validate content length header
	validatedSize, err := validateContentLength(r.Header.Get("Content-Length"))
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Process the upload
	body, err := processChunkedUpload(r, validatedSize)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Verify signature if provided
	sig := r.Header.Get(signatureHeader)
	if sig != "" {
		if !verifySignature(body, sig) {
			http.Error(w, "invalid signature", http.StatusForbidden)
			return
		}
	}

	// Process the uploaded data
	hash := sha256.Sum256(body)
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, `{"status":"success","size":%d,"hash":"%s"}`, len(body), hex.EncodeToString(hash[:]))
}

// healthHandler returns service health status
func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/v1/upload", uploadHandler)
	mux.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	server := &http.Server{
		Addr:    ":" + port,
		Handler: mux,
	}

	fmt.Printf("Server starting on port %s\n", port)
	if err := server.ListenAndServe(); err != nil {
		fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
		os.Exit(1)
	}
}
